package dev.jdoc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.InputStream;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Characterizes the current model using HTML generated by each supported JDK's javadoc. */
class JavadocFixtureTest {
  private static Document fixture(String release, String type) throws IOException {
    String relative = "fixtures/" + release + "/fixture/api/" + type + ".html";
    try (InputStream resource = JavadocFixtureTest.class.getClassLoader()
        .getResourceAsStream(relative)) {
      assertNotNull(resource, "Missing generated fixture: " + relative);
      return Jsoup.parse(resource, "UTF-8",
          Versions.base(release) + "fixture/api/" + type + ".html");
    }
  }

  private static DocModel model(String release, String type, Document page) {
    return JavadocParser.parse(page, "fixture.api." + type,
        Versions.base(release) + "fixture/api/" + type + ".html", release);
  }

  @ParameterizedTest
  @ValueSource(strings = {"17", "21", "25"})
  void textOverloadsAndVarargsFollowTheGeneratedSummary(String release) throws IOException {
    Document page = fixture(release, "Text");
    DocModel doc = model(release, "Text", page);
    assertEquals(3, doc.schemaVersion);
    assertEquals("fixture.api.Text", doc.name);
    assertEquals(List.of("format", "valueOf", "valueOf"),
        doc.methods.stream().map(m -> m.name).toList());
    assertEquals(List.of("valueOf(boolean)", "valueOf(char[],int,int)"),
        doc.methods.stream().filter(m -> m.name.equals("valueOf")).map(m -> m.anchor).toList());
    assertEquals(List.of("char[]", "int", "int"), doc.methods.get(2).parameterTypes);
    assertEquals(List.of("String", "Object[]"), doc.methods.get(0).parameterTypes);
    assertEquals(2, doc.constructors.size());
    assertEquals(List.of("MAX_VALUE"), doc.fields.stream().map(m -> m.name).toList());
    assertTrue(doc.methods.get(2).details.contains("Returns:\n  a new text value"));

    // Current v2 behavior flattens structured documentation into one string.
    assertTrue(page.selectFirst("#method-detail pre") != null);
    assertTrue(doc.methods.get(0).description.contains("Text.format(\"%s\", \"hello\");"));
    assertFalse(doc.methods.get(0).description.contains("\n"));
  }

  @ParameterizedTest
  @ValueSource(strings = {"17", "21", "25"})
  void sequenceSeparatesDeclaredAndInheritedMethods(String release) throws IOException {
    Document page = fixture(release, "Sequence");
    assertEquals("BaseSequence.html#containsAll(java.util.Collection)",
        page.selectFirst("section.method-summary div.inherited-list a[href*=containsAll]")
            .attr("href"));
    assertEquals(Versions.base(release) + "fixture/api/BaseSequence.html#containsAll(java.util.Collection)",
        page.selectFirst("section.method-summary div.inherited-list a[href*=containsAll]")
            .attr("abs:href"));
    assertEquals("SequenceView.html#stream()",
        page.selectFirst("section.method-summary div.inherited-list a[href*=stream]")
            .attr("href"));
    DocModel doc = model(release, "Sequence", page);
    assertEquals(List.of("add"), doc.methods.stream().map(m -> m.name).toList());
    assertTrue(doc.inherited.stream().anyMatch(m -> m.name.equals("stream")
        && m.declaringType.equals("fixture.api.SequenceView")));
    assertTrue(doc.inherited.stream().anyMatch(m -> m.name.equals("containsAll")
        && m.declaringType.equals("fixture.api.BaseSequence")));
    assertFalse(doc.inherited.stream().anyMatch(m -> m.declaringType.equals("java.lang.Object")));
  }

  @ParameterizedTest
  @ValueSource(strings = {"17", "21", "25"})
  void failureHasFiveConstructorsAndNoDirectMethods(String release) throws IOException {
    DocModel doc = model(release, "Failure", fixture(release, "Failure"));
    assertTrue(doc.methods.isEmpty());
    assertEquals(5, doc.constructors.size());
    assertEquals(List.of("String", "Throwable", "boolean", "boolean"),
        doc.constructors.get(3).parameterTypes);
    assertTrue(doc.constructors.get(3).signature.startsWith("protected Failure("));
    assertFalse(doc.description.isBlank());
  }

  @ParameterizedTest
  @ValueSource(strings = {"17", "21", "25"})
  void enumPageModelsConstantsAndMethods(String release) throws IOException {
    Document page = fixture(release, "Unit");
    assertEquals(2, page.select("section.constants-summary .col-first a").size());
    DocModel doc = model(release, "Unit", page);
    assertEquals(List.of("label", "valueOf", "values"),
        doc.methods.stream().map(m -> m.name).toList());
    assertEquals(List.of("String"), doc.methods.get(1).parameterTypes);
    assertEquals(List.of("FIRST", "SECOND"),
        doc.enumConstants.stream().map(m -> m.name).toList());
  }

  @ParameterizedTest
  @ValueSource(strings = {"17", "21", "25"})
  void interfacePageContainsNestedTypeAndDirectDefaultAndStaticMethods(String release)
      throws IOException {
    Document page = fixture(release, "Dictionary");
    assertEquals("Dictionary.Entry.html",
        page.selectFirst("section.nested-class-summary a[href*=Entry]").attr("href"));
    DocModel doc = model(release, "Dictionary", page);
    assertEquals(List.of("entry", "get", "getOrDefault"),
        doc.methods.stream().map(m -> m.name).toList());
    assertTrue(doc.methods.get(0).signature.contains("static"));
    assertTrue(doc.methods.get(2).signature.contains("default"));
    assertEquals(List.of("Dictionary.Entry"),
        doc.nestedTypes.stream().map(m -> m.name).toList());
  }
}
